import { type DateArg, endOfDay, endOfMonth, endOfYear, startOfDay, startOfMonth, startOfYear } from 'date-fns'
import type { Option } from '@/types/base'
import type { AdvancedFilterFormValueOutput, BasicSearchFormValueOutput } from './form'

// Smart filter operation
export const smartFilterOperations = [
  'equalsTo',
  'doesNotEqualTo',
  'contains',
  'isLessThan',
  'isLessThanOrEqualTo',
  'isGreaterThan',
  'isGreaterThanOrEqualTo',
  'isBetween',
  'hasAnyOf',
  'hasAllOf'
] as const

export type SmartFilterOperation = (typeof smartFilterOperations)[number]

// Smart filter type
export const smartFilterTypes = [
  'input',
  'number',
  'date',
  'selectWithOptions',
  'selectWithQuery',
  'selectWithInfiniteQuery',
  'multiSelectWithOptions',
  'multiSelectWithQuery',
  'multiSelectWithInfiniteQuery'
] as const

export type SmartFilterType = (typeof smartFilterTypes)[number]

// Smart filter api operation
export const smartFilterApiOperations = {
  equal: '==',
  notEqual: '!=',
  lessThan: '<',
  greaterThan: '>',
  lessThanOrEqual: '<=',
  greaterThanOrEqual: '>=',
  contain: '@=',
  startWith: '_=',
  notStartWith: '!_=',
  caseInsensitiveStringContain: '@=*',
  caseInsensitiveStringNotContain: '!@=*',
  caseInsensitiveStartWith: '_=*',
  caseInsensitiveNotStartWith: '!_=*',
  caseInsensitiveEqual: '==*',
  caseInsensitiveNotEqual: '!=*',
  equalArray: '[]'
} as const

export type SmartFilterApiOperation = (typeof smartFilterApiOperations)[keyof typeof smartFilterApiOperations]

// Smart filter logical operation
export const smartFilterLogicalOperation = {
  and: ',',
  or: '|'
} as const

// Operation per type
export const operationsPerType: Record<SmartFilterType, SmartFilterOperation[]> = {
  input: ['equalsTo', 'doesNotEqualTo', 'contains'],
  number: [
    'equalsTo',
    'doesNotEqualTo',
    'isLessThan',
    'isLessThanOrEqualTo',
    'isGreaterThan',
    'isGreaterThanOrEqualTo',
    'isBetween'
  ],
  date: ['equalsTo', 'isLessThan', 'isLessThanOrEqualTo', 'isGreaterThan', 'isGreaterThanOrEqualTo', 'isBetween'],
  selectWithOptions: ['equalsTo', 'doesNotEqualTo', 'hasAnyOf'],
  selectWithQuery: ['equalsTo', 'doesNotEqualTo', 'hasAnyOf'],
  selectWithInfiniteQuery: ['equalsTo', 'doesNotEqualTo', 'hasAnyOf'],
  multiSelectWithOptions: ['hasAnyOf', 'hasAllOf'],
  multiSelectWithQuery: ['hasAnyOf', 'hasAllOf'],
  multiSelectWithInfiniteQuery: ['hasAnyOf', 'hasAllOf']
} as const

// Api operation per operation
export const apiOperationPerOperation: Partial<Record<SmartFilterOperation, SmartFilterApiOperation>> = {
  equalsTo: '==',
  doesNotEqualTo: '!=',
  isLessThan: '<',
  isLessThanOrEqualTo: '<=',
  isGreaterThan: '>',
  isGreaterThanOrEqualTo: '>=',
  contains: '@='
} as const

// Filter
const filterTypesWithOptions = ['selectWithOptions', 'multiSelectWithOptions'] as const
type FilterTypeWithOptions = (typeof filterTypesWithOptions)[number]

const filterTypesWithQuery = [
  'selectWithQuery',
  'selectWithInfiniteQuery',
  'multiSelectWithQuery',
  'multiSelectWithInfiniteQuery'
] as const
type FilterTypeWithQuery = (typeof filterTypesWithQuery)[number]

type OtherFilterType = Exclude<SmartFilterType, FilterTypeWithOptions | FilterTypeWithQuery>

export interface BaseFilter {
  label: string
  name: string
  dateFormat?: 'date' | 'month' | 'year'
}

export interface FilterWithOptions extends BaseFilter {
  type: FilterTypeWithOptions
  options: Option<string>[]
}

export interface FilterWithQuery extends BaseFilter {
  type: FilterTypeWithQuery
  apiPath: string
}

interface OtherFilter extends BaseFilter {
  type: OtherFilterType
}

export type Filter = FilterWithOptions | FilterWithQuery | OtherFilter

// Transform form value to api filters param
const periodHandlerPerDateFormat: Record<
  NonNullable<Filter['dateFormat']>,
  {
    start: (date: DateArg<Date>) => Date
    end: (date: DateArg<Date>) => Date
  }
> = {
  date: { start: startOfDay, end: endOfDay },
  month: { start: startOfMonth, end: endOfMonth },
  year: { start: startOfYear, end: endOfYear }
}

export function transformFormValueToApiFiltersParam(
  value: BasicSearchFormValueOutput['keyword'] | AdvancedFilterFormValueOutput['filters'],
  filters: Filter[],
  handler?: {
    basicSearch?: string | ((value: BasicSearchFormValueOutput['keyword']) => string)
    advancedFilter?: (value: AdvancedFilterFormValueOutput['filters']) => string
  }
) {
  // Base filter
  if (typeof value === 'string') {
    if (value === '') {
      return undefined
    }

    if (typeof handler?.basicSearch === 'function') {
      return handler.basicSearch(value)
    }

    const baseFilterKey =
      handler?.basicSearch && typeof handler.basicSearch === 'string' ? handler.basicSearch : 'value'
    return `${baseFilterKey}${apiOperationPerOperation.contains}${value}`
  }

  // Advanced filter
  const filtersMap = filters.reduce<Record<string, Omit<Filter, 'name'>>>((acc, filter) => {
    acc[filter.name] = { ...filter }
    return acc
  }, {})

  return handler?.advancedFilter
    ? handler.advancedFilter(value)
    : value
        .map(({ name, operation, value }, index) => {
          const logicalOperation = index > 0 ? smartFilterLogicalOperation.and : ''
          const { type, dateFormat = 'date' } = filtersMap[name]

          // Common
          // Has any of operation
          if (Array.isArray(value.default) && operation === 'hasAnyOf') {
            return `${logicalOperation}${name}${smartFilterApiOperations.equal}${value.default.join(smartFilterLogicalOperation.or)}`
          }

          // Has all of operation
          if (Array.isArray(value.default) && operation === 'hasAllOf') {
            return value.default
              .map((item) => `${logicalOperation}${name}${smartFilterApiOperations.equal}${item}`)
              .join(smartFilterLogicalOperation.and)
          }

          switch (type) {
            case 'number': {
              // Is between operation
              if (operation === 'isBetween') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${value.additional.from}${smartFilterLogicalOperation.and}${name}${smartFilterApiOperations.lessThanOrEqual}${value.additional.to}`
              }
              break
            }

            case 'date': {
              const dateValue = value.default as string

              // Equals operation
              if (operation === 'equalsTo') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].start(dateValue).toISOString()}${smartFilterLogicalOperation.and}${name}${smartFilterApiOperations.lessThanOrEqual}${periodHandlerPerDateFormat[dateFormat].end(dateValue).toISOString()}`
              }

              // Is less than operation
              if (operation === 'isLessThan') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].start(dateValue).toISOString()}`
              }

              // Is less than or equal to operation
              if (operation === 'isLessThanOrEqualTo') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].end(dateValue).toISOString()}`
              }

              // Is greater than operation
              if (operation === 'isGreaterThan') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].end(dateValue).toISOString()}`
              }

              // Is greater than or equal to operation
              if (operation === 'isGreaterThanOrEqualTo') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].start(dateValue).toISOString()}`
              }

              // Is between operation
              if (operation === 'isBetween') {
                return `${logicalOperation}${name}${smartFilterApiOperations.greaterThanOrEqual}${periodHandlerPerDateFormat[dateFormat].start(value.additional.from).toISOString()}${smartFilterLogicalOperation.and}${name}${smartFilterApiOperations.lessThanOrEqual}${periodHandlerPerDateFormat[dateFormat].end(value.additional.to).toISOString()}`
              }

              break
            }

            default:
              break
          }

          // Normal filter
          return `${logicalOperation}${name}${apiOperationPerOperation[operation]}${value.default}`
        })
        .join('')
}

import {
  type AppFieldExtendedReactFormApi,
  createFormHook,
  createFormHookContexts,
  type FormAsyncValidateOrFn,
  type FormValidateOrFn
} from '@tanstack/react-form'
import z from 'zod'
import type { Option } from '@/types/base'
import { type SmartFilterOperation, smartFilterOperations, smartFilterTypes } from './base'

// Create form hook
const { fieldContext, formContext, useFieldContext, useFormContext } = createFormHookContexts()
const { useAppForm, withForm } = createFormHook({
  fieldComponents: {},
  formComponents: {},
  fieldContext,
  formContext
})

export { useAppForm, useFieldContext, useFormContext, withForm }

// Basic search form
export const basicSearchFormSchema = z.object({
  keyword: z.string().trim()
})

export type BasicSearchFormValueInput = z.input<typeof basicSearchFormSchema>
export type BasicSearchFormValueOutput = z.output<typeof basicSearchFormSchema>
export const defaultBasicSearchFormValue: BasicSearchFormValueInput = { keyword: '' }

// Advanced filter form
export const advancedFilterFormSchema = z.object({
  filters: z.array(
    z
      .object({
        name: z.string().trim(),
        operation: z.literal(smartFilterOperations),
        type: z.literal(smartFilterTypes),
        value: z.object({
          default: z.union([z.string().trim(), z.array(z.string()).min(1, 'Please enter/select the information')]),
          additional: z.object({
            from: z.string(),
            to: z.string()
          })
        })
      })
      .superRefine((fieldValues, ctx) => {
        const { value, operation } = fieldValues

        if (operation === 'isBetween') {
          if (value.additional.from === '') {
            const invalidFields = ['value.additional', 'value.additional.from']
            for (const invalidField of invalidFields) {
              ctx.addIssue({
                path: [invalidField],
                message: 'Please enter/select the information',
                code: 'custom'
              })
            }
          }

          if (value.additional.to === '') {
            const invalidFields = ['value.additional', 'value.additional.to']
            for (const invalidField of invalidFields) {
              ctx.addIssue({
                path: [invalidField],
                message: 'Please enter/select the information',
                code: 'custom'
              })
            }
          }
        } else if (value.default === '') {
          ctx.addIssue({
            path: ['value.default'],
            message: 'Please enter/select the information',
            code: 'custom'
          })
        }
      })
  )
})

export type AdvancedFilterFormValueInput = z.input<typeof advancedFilterFormSchema>
export type AdvancedFilterFormValueOutput = z.output<typeof advancedFilterFormSchema>
export const defaultAdvancedFilterFormValue: AdvancedFilterFormValueInput = { filters: [] }

export function useAdvancedFilterForm() {
  return useFormContext() as unknown as AppFieldExtendedReactFormApi<
    AdvancedFilterFormValueInput,
    FormValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormAsyncValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormAsyncValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormAsyncValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormAsyncValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    FormAsyncValidateOrFn<AdvancedFilterFormValueInput> | undefined,
    unknown,
    Record<string, React.ComponentType<unknown>>,
    Record<string, React.ComponentType<unknown>>
  >
}

// Default string value
export const defaultStringValue: AdvancedFilterFormValueInput['filters'][number]['value'] = {
  default: '',
  additional: {
    from: '',
    to: ''
  }
} as const

// Default string array value
export const defaultStringArrayValue: AdvancedFilterFormValueInput['filters'][number]['value'] = {
  default: [],
  additional: {
    from: '',
    to: ''
  }
} as const

// Default value per operation
export const defaultValuePerOperation: Record<
  SmartFilterOperation,
  AdvancedFilterFormValueInput['filters'][number]['value']
> = {
  equalsTo: defaultStringValue,
  doesNotEqualTo: defaultStringValue,
  isLessThan: defaultStringValue,
  isLessThanOrEqualTo: defaultStringValue,
  isGreaterThan: defaultStringValue,
  isGreaterThanOrEqualTo: defaultStringValue,
  contains: defaultStringValue,
  isBetween: defaultStringValue,
  hasAnyOf: defaultStringArrayValue,
  hasAllOf: defaultStringArrayValue
} as const

/**
 * Update reference of selected item bacause queryData will be changed after refetching
 */
export function updateSelectedItemReferencesAndGetItems({
  value,
  queryData
}: {
  value: Option | Option[] | null
  queryData: Option[]
}): Option[] {
  // Multiple
  if (Array.isArray(value)) {
    if (value.length > 0) {
      // Update reference of selected item bacause of queryData will be changed after refetching
      queryData.forEach((item, index) => {
        const valueIndex = value.findIndex((valueItem) => valueItem.value === item.value)
        if (valueIndex >= 0) {
          queryData[index] = value[valueIndex]
        }
      })
    }

    return queryData
  }

  // Single
  if (value) {
    const valueIndex = queryData.findIndex((item) => item.value === value.value)
    if (valueIndex >= 0) {
      // Update reference of selected item bacause of queryData will be changed after refetching
      queryData[valueIndex] = value
    }
  }

  return queryData
}

import {
  type DefaultError,
  type GetNextPageParamFunction,
  type InfiniteData,
  type QueryKey,
  type UseInfiniteQueryResult,
  useInfiniteQuery,
  useQuery
} from '@tanstack/react-query'
import { useDebounce } from '@uidotdev/usehooks'
import { type UIEvent, useMemo, useState } from 'react'
import { executeAxios } from '@/lib/axios'
import type { OptionsInfiniteQueryData, PaginationQueryData } from '@/types/api'
import type { Option } from '@/types/base'

// Use get options query
export function useGetOptionsQuery({ apiPath }: { apiPath: string }) {
  const getOptionsQuery = useQuery<{
    responseData: {
      rows: Option[]
    }
  }>({
    queryKey: apiPath.split('?'),
    queryFn: ({ signal }) => {
      return executeAxios({ url: apiPath, method: 'GET', signal })
    }
  })

  const options = useMemo(() => {
    return getOptionsQuery.data?.responseData?.rows ?? []
  }, [getOptionsQuery.data])

  return {
    getOptionsQuery,
    options
  }
}

// Infinite query page size
export const infiniteQueryPageSize = 100

// Get next page param
export const getNextPageParam: GetNextPageParamFunction<number, PaginationQueryData> = (queryFn, _, page) => {
  const {
    responseData: { count, pageSize }
  } = queryFn
  const queryPage = page as unknown as number
  const totalPage = Math.ceil(count / pageSize)

  if (!totalPage || queryPage === totalPage) {
    return null
  }
  return queryPage + 1
}

// Fetch next page
export function fetchNextPage({
  event,
  infiniteQuery
}: {
  event: UIEvent<HTMLDivElement>
  infiniteQuery: UseInfiniteQueryResult
}) {
  const { scrollTop, offsetHeight, scrollHeight } = event.target as HTMLDivElement
  if (
    scrollTop + offsetHeight >= scrollHeight - 28 * 20 &&
    !infiniteQuery.isFetchingNextPage &&
    infiniteQuery.hasNextPage
  ) {
    infiniteQuery.fetchNextPage()
  }
}

// Use get options infinite query
export function useGetOptionsInfiniteQuery({ apiPath }: { apiPath: string }) {
  const [searchKeyword, setSearchKeyword] = useState('')
  const debouncedSearchKeyword = useDebounce(searchKeyword.trim(), 400)

  const getOptionsInfiniteQuery = useInfiniteQuery<
    OptionsInfiniteQueryData,
    DefaultError,
    InfiniteData<OptionsInfiniteQueryData>,
    QueryKey,
    number
  >({
    queryKey: [...apiPath.split('?'), debouncedSearchKeyword],
    queryFn: ({ signal, pageParam }) => {
      return executeAxios({
        url: `${apiPath}${apiPath.includes('?') ? '&' : '?'}page=${pageParam}&pageSize=${infiniteQueryPageSize}${debouncedSearchKeyword ? `&searchQuery=${debouncedSearchKeyword}` : ''}`,
        method: 'GET',
        signal
      })
    },
    initialPageParam: 1,
    getNextPageParam
  })

  const options = useMemo<Option[]>(() => {
    return getOptionsInfiniteQuery.data?.pages.flatMap((page) => page.responseData.rows) ?? []
  }, [getOptionsInfiniteQuery.data])

  return {
    getOptionsInfiniteQuery,
    options,
    searchKeyword,
    debouncedSearchKeyword,
    setSearchKeyword
  }
}

import { useMemo } from 'react'
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from '@/components/atoms/select'
import type { Option } from '@/types/base'
import { type AdvancedFilterFormValueInput, useFieldContext } from './lib/form'
import { useSmartFilterContext } from './smart-filter'

export default function AdvancedFilterNameField({
  formFilters
}: {
  formFilters: AdvancedFilterFormValueInput['filters']
}) {
  const { filters } = useSmartFilterContext()
  const field = useFieldContext<AdvancedFilterFormValueInput['filters'][number]['name']>()

  const options = useMemo<Option<string>[]>(() => {
    const selectedFilters = formFilters.map((field) => field.name)
    return filters
      .filter((filter) => filter.name === field.state.value || !selectedFilters.includes(filter.name))
      .map((filter) => ({
        value: filter.name,
        label: filter.label
      }))
  }, [filters, formFilters, field.state.value])

  return (
    <Select items={options} onValueChange={(value) => field.handleChange(value as string)} value={field.state.value}>
      <SelectTrigger>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectGroup>
      </SelectContent>
    </Select>
  )
}

import { useMemo } from 'react'
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from '@/components/atoms/select'
import type { Option } from '@/types/base'
import { operationsPerType, type SmartFilterOperation } from './lib/base'
import { type AdvancedFilterFormValueInput, useFieldContext } from './lib/form'
import { useSmartFilterContext } from './smart-filter'

const operationLabels: Record<string, Record<string, string | undefined> | undefined> = {
  base: {
    equalsTo: 'Equals to',
    doesNotEqualTo: 'Does not equal to',
    contains: 'Contains',
    isBetween: 'Is between',
    hasAnyOf: 'Has any of',
    hasAllOf: 'Has all of'
  },
  number: {
    isLessThan: 'Is less than',
    isLessThanOrEqualTo: 'Is less than or equal to',
    isGreaterThan: 'Is greater than',
    isGreaterThanOrEqualTo: 'Is greater than or equal to'
  },
  date: {
    isLessThan: 'Is before',
    isLessThanOrEqualTo: 'Is before or equal to',
    isGreaterThan: 'Is after',
    isGreaterThanOrEqualTo: 'Is after or equal to'
  }
}

export default function AdvancedFilterOperationField({ formFilterName }: { formFilterName: string }) {
  const { filters } = useSmartFilterContext()
  const field = useFieldContext<AdvancedFilterFormValueInput['filters'][number]['operation']>()

  const options = useMemo<Option<SmartFilterOperation>[]>(() => {
    const type = filters.find((filter) => filter.name === formFilterName)?.type
    return type
      ? operationsPerType[type].map((operation) => ({
          value: operation,
          label: operationLabels[type]?.[operation] ?? operationLabels.base?.[operation] ?? ''
        }))
      : []
  }, [filters, formFilterName])

  return (
    <Select
      items={options}
      onValueChange={(value) => {
        if (value) {
          field.handleChange(value)
        }
      }}
      value={field.state.value}
    >
      <SelectTrigger>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectGroup>
      </SelectContent>
    </Select>
  )
}

import { toDate } from 'date-fns'
import { DatePicker, DateRangePicker } from '@/components/atoms/date-picker'
import { Field, FieldError } from '@/components/atoms/field'
import type { AdvancedFilterValueFieldComponentProps } from './advanced-filter-value-field'
import { useAdvancedFilterForm } from './lib/form'

export default function AdvancedFilterValueDateField({
  index,
  selectedFilter,
  formFilterOperation
}: AdvancedFilterValueFieldComponentProps) {
  const advancedFilterForm = useAdvancedFilterForm()

  // Template
  // Is between
  if (formFilterOperation === 'isBetween') {
    return (
      <advancedFilterForm.AppField name={`filters[${index}].value.additional`}>
        {(field) => {
          const invalid = field.state.meta.isTouched && !field.state.meta.isValid

          return (
            <Field data-invalid={invalid}>
              <DateRangePicker
                onValueChange={(value) => {
                  field.handleChange({
                    from: value?.from?.toISOString() ?? '',
                    to: value?.to?.toISOString() ?? ''
                  })
                }}
                placeholder={`Select ${selectedFilter.label.toLowerCase()} range`}
                value={{
                  from: field.state.value.from ? new Date(field.state.value.from) : undefined,
                  to: field.state.value.to ? new Date(field.state.value.to) : undefined
                }}
              />
              {invalid && <FieldError errors={field.state.meta.errors} />}
            </Field>
          )
        }}
      </advancedFilterForm.AppField>
    )
  }

  // Others
  return (
    <advancedFilterForm.AppField name={`filters[${index}].value.default`}>
      {(field) => {
        const invalid = field.state.meta.isTouched && !field.state.meta.isValid
        return (
          <Field data-invalid={invalid}>
            <DatePicker
              onValueChange={(value) => {
                field.handleChange(value?.toISOString() ?? '')
              }}
              placeholder={`Select ${selectedFilter.label.toLowerCase()}`}
              value={field.state.value ? toDate(field.state.value as string) : null}
            />
            {invalid && <FieldError errors={field.state.meta.errors} />}
          </Field>
        )
      }}
    </advancedFilterForm.AppField>
  )
}

import { type JSX, type LazyExoticComponent, lazy, useMemo } from 'react'
import type { Filter, SmartFilterType } from './lib/base'
import type { AdvancedFilterFormValueInput } from './lib/form'
import { useSmartFilterContext } from './smart-filter'

export interface AdvancedFilterValueFieldProps {
  index: number
  formFilterName: AdvancedFilterFormValueInput['filters'][number]['name']
  formFilterOperation: AdvancedFilterFormValueInput['filters'][number]['operation']
  formFilterValueAdditional: AdvancedFilterFormValueInput['filters'][number]['value']['additional']
}

export type AdvancedFilterValueFieldComponentProps = AdvancedFilterValueFieldProps & {
  selectedFilter: Filter
}

const fieldComponents: {
  [key in SmartFilterType]: LazyExoticComponent<(props: AdvancedFilterValueFieldComponentProps) => JSX.Element | null>
} = {
  input: lazy(() => import('./advanced-filter-value-input-field')),
  number: lazy(() => import('./advanced-filter-value-number-field')),
  date: lazy(() => import('./advanced-filter-value-date-field')),
  selectWithOptions: lazy(() => import('./advanced-filter-value-select-with-options-field')),
  selectWithQuery: lazy(() => import('./advanced-filter-value-select-with-query-field')),
  selectWithInfiniteQuery: lazy(() => import('./advanced-filter-value-select-with-infinite-query-field')),
  multiSelectWithOptions: lazy(() => import('./advanced-filter-value-multi-select-with-options-field')),
  multiSelectWithQuery: lazy(() => import('./advanced-filter-value-multi-select-with-query-field')),
  multiSelectWithInfiniteQuery: lazy(() => import('./advanced-filter-value-multi-select-with-infinite-query-field'))
}

export default function AdvancedFilterValueField({
  formFilterName,
  formFilterOperation,
  ...props
}: AdvancedFilterValueFieldProps) {
  const { filters } = useSmartFilterContext()

  const selectedFilter = useMemo(() => {
    return filters.find((filter) => filter.name === formFilterName)
  }, [filters, formFilterName])

  // Template
  if (!selectedFilter) {
    return null
  }

  const FieldComponent = fieldComponents[selectedFilter.type]
  return (
    <FieldComponent
      formFilterName={formFilterName}
      formFilterOperation={formFilterOperation}
      key={`${formFilterName}-${formFilterOperation}`}
      selectedFilter={selectedFilter}
      {...props}
    />
  )
}

import { Field, FieldError } from '@/components/atoms/field'
import { Input } from '@/components/atoms/input'
import type { AdvancedFilterValueFieldComponentProps } from './advanced-filter-value-field'
import { useAdvancedFilterForm } from './lib/form'

export default function AdvancedFilterValueInputField({
  index,
  selectedFilter
}: AdvancedFilterValueFieldComponentProps) {
  const advancedFilterForm = useAdvancedFilterForm()

  return (
    <advancedFilterForm.AppField name={`filters[${index}].value.default`}>
      {(field) => {
        const invalid = field.state.meta.isTouched && !field.state.meta.isValid
        return (
          <Field data-invalid={invalid}>
            <Input
              aria-invalid={invalid}
              id={field.name}
              name={field.name}
              onBlur={field.handleBlur}
              onChange={(e) => field.handleChange(e.target.value)}
              placeholder={`Enter ${selectedFilter.label.toLowerCase()}`}
              value={field.state.value}
            />
            {invalid && <FieldError errors={field.state.meta.errors} />}
