// Execute axios
export const executeAxios = <T>(config: AxiosRequestConfig, options?: AxiosRequestConfig): Promise<T> => {
  const source = Axios.CancelToken.source()
  const promise = axios<T>({
    ...config,
    ...options
  }).then(({ data, status }) => {
    return data instanceof Blob ? data : { ...data, statusCode: status }
  })

  // @ts-expect-error not exist cancel
  promise.cancel = () => {
    source.cancel('Query was cancelled')
  }
  return promise
}

import type { Option } from '@/types/base'

export interface BaseAPIData<Data> {
  message: string | null
  message_en: string | null
  responseData: Data
  status: 'fail' | 'success'
  statusCode: number
  timeStamp: string
}

export type QueryData<Data = unknown> = BaseAPIData<Data> & {
  violations: Array<{
    code: number
    message: string
    action: Array<{
      location: string
      msg: string
      path: string
      value: string
    }> | null
  }> | null
}

export type PaginationQueryData<Row = unknown> = QueryData<{
  count: number
  page: number
  pageSize: number
  rows: Row[]
}>

export type OptionsInfiniteQueryData = PaginationQueryData<Option>

export interface Option<T = string> {
  value: T
  label: string
}
